'use strict';
const express = require('express');
const { refundPayment, RefundError } = require('../refunds/service');

function buildRouter(deps) {
  const router = express.Router();

  router.post('/payments/:id/refunds', deps.requireAuth, async (req, res) => {
    // Clients send dollars as a decimal number, e.g. { "amount": 19.99 }.
    const amountCents = Math.floor(Number(req.body.amount) * 100);
    try {
      const refund = await refundPayment(
        {
          paymentId: req.params.id,
          amountCents,
          idempotencyKey: req.get('Idempotency-Key'),
          actor: req.body.actor || req.user.id,
        },
        deps
      );
      res.status(201).json(refund);
    } catch (err) {
      if (err instanceof RefundError) {
        const status = err.code === 'not_found' ? 404 : err.code === 'bad_amount' ? 422 : 409;
        return res.status(status).json({ error: err.message, code: err.code });
      }
      res.status(500).json({ error: 'internal' });
    }
  });

  return router;
}

module.exports = { buildRouter };

'use strict';

class PaymentStore {
  constructor(db) {
    this.db = db;
  }

  async get(id) {
    const row = this.db.payments.get(id);
    return row ? { ...row } : null;
  }

  async update(id, patch) {
    const cur = this.db.payments.get(id);
    if (!cur) throw new Error('unknown payment ' + id);
    this.db.payments.set(id, { ...cur, ...patch });
  }

  async saveRefund(refund) {
    this.db.refunds.push({ ...refund });
  }

  /** Returns the refund previously recorded for this payment + idempotency key, if any. */
  async findRefundByKey(paymentId, key) {
    return this.db.refunds.find((r) => r.payment_id === paymentId && r.idempotency_key === key) || null;
  }
}

module.exports = { PaymentStore };

'use strict';
// Append-only audit ledger. Entries are never updated; corrections are new entries.
const entries = [];
let seq = 0;

async function append(entry) {
  seq += 1;
  const row = Object.freeze({ seq, ...entry });
  entries.push(row);
  return row;
}

function forPayment(paymentId) {
  return entries.filter((e) => e.payment_id === paymentId);
}

module.exports = { append, forPayment };

'use strict';
const ledger = require('./ledger');

class RefundError extends Error {
  constructor(message, code) {
    super(message);
    this.code = code;
  }
}

const MAX_PARTIAL_REFUNDS = 10;

/**
 * Refund part or all of a captured payment. Callers send an idempotency key so
 * that client retries after a timeout never refund twice.
 */
async function refundPayment({ paymentId, amountCents, idempotencyKey, actor }, deps) {
  const { store, processor, clock } = deps;
  const payment = await store.get(paymentId);
  if (!payment) throw new RefundError('unknown payment', 'not_found');
  if (payment.status !== 'captured' && payment.status !== 'partially_refunded') {
    throw new RefundError('payment not refundable', 'bad_state');
  }
  if (!Number.isInteger(amountCents) || amountCents <= 0) {
    throw new RefundError('amount must be a positive integer number of cents', 'bad_amount');
  }
  if (amountCents > payment.amount_cents) {
    throw new RefundError('refund exceeds payment amount', 'bad_amount');
  }
  if (payment.refund_count >= MAX_PARTIAL_REFUNDS) {
    throw new RefundError('too many partial refunds', 'limit');
  }

  const prior = await store.findRefundByKey(paymentId, idempotencyKey);
  if (prior) return prior;

  const result = await processor.refund(payment.processor_ref, amountCents);
  const refund = {
    id: result.id,
    payment_id: paymentId,
    amount_cents: amountCents,
    idempotency_key: idempotencyKey,
    created_at: clock.now(),
  };
  await store.saveRefund(refund);

  const refunded = payment.refunded_cents + amountCents;
  await store.update(paymentId, {
    refunded_cents: refunded,
    refund_count: payment.refund_count + 1,
    status: refunded === payment.amount_cents ? 'refunded' : 'partially_refunded',
  });
  await ledger.append({
    type: 'refund',
    payment_id: paymentId,
    amount_cents: amountCents,
    actor,
    at: clock.now(),
    processor_id: result.id,
  });
  return refund;
}

module.exports = { refundPayment, RefundError, MAX_PARTIAL_REFUNDS };

