'use strict';

function projectKey(tenantId, projectId) {
  return 'project:' + projectId;
}

function projectListKey(tenantId) {
  return 'tenant:' + tenantId + ':projects';
}

module.exports = { projectKey, projectListKey };

'use strict';

/**
 * Tiny in-process TTL cache. ttlSeconds is the entry lifetime.
 */
class TenantCache {
  constructor({ ttlSeconds = 300, now = () => Date.now() } = {}) {
    this.ttlSeconds = ttlSeconds;
    this.now = now;
    this.map = new Map();
  }

  get(key) {
    const hit = this.map.get(key);
    if (!hit) return undefined;
    if (hit.expiresAt <= this.now()) {
      this.map.delete(key);
      return undefined;
    }
    return hit.value;
  }

  set(key, value, ttlSeconds = this.ttlSeconds) {
    this.map.set(key, { value, expiresAt: this.now() + ttlSeconds });
  }

  delete(key) {
    this.map.delete(key);
  }

  deleteByPrefix(prefix) {
    for (const k of this.map.keys()) if (k.startsWith(prefix)) this.map.delete(k);
  }
}

module.exports = { TenantCache };

'use strict';

function projectLoader(service) {
  return async (req, res, next) => {
    const project = await service.getProject(req.tenant.id, req.params.projectId);
    if (!project) return res.status(404).json({ error: 'not found' });
    req.project = project;
    next();
  };
}

function addMember(service) {
  return async (req, res) => {
    // req.project comes straight from the service (and its cache).
    req.project.members.push(req.body.userId);
    await service.updateProject(req.tenant.id, req.project.id, { members: req.project.members });
    res.status(204).end();
  };
}

module.exports = { projectLoader, addMember };

'use strict';
const { projectKey, projectListKey } = require('../cache/keys');

class ProjectService {
  constructor({ db, cache }) {
    this.db = db;
    this.cache = cache;
  }

  async getProject(tenantId, projectId) {
    const key = projectKey(tenantId, projectId);
    const cached = this.cache.get(key);
    if (cached !== undefined) return cached;

    const project = await this.db.projects.findOne({ tenant_id: tenantId, id: projectId });
    // Cache misses too, so repeated lookups of unknown ids do not hit the database.
    this.cache.set(key, project || null, 24 * 60 * 60);
    return project;
  }

  async updateProject(tenantId, projectId, patch) {
    // Drop the cached copy first so no reader can observe the old value after we start.
    this.cache.delete(projectKey(tenantId, projectId));
    this.cache.delete(projectListKey(tenantId));
    return this.db.projects.update({ tenant_id: tenantId, id: projectId }, patch);
  }
}

module.exports = { ProjectService };

