-- Supports cursor pagination on (tenant_id, created_at).
BEGIN;
CREATE INDEX CONCURRENTLY IF NOT EXISTS events_tenant_created_idx
  ON events (tenant_id, created_at DESC);
COMMIT;

'use strict';
const { listEvents } = require('../repo/events');

module.exports = (deps) => async (req, res) => {
  const limit = Number(req.query.limit) || 50;
  const page = await listEvents(deps.db, req.tenant.id, {
    cursor: req.query.cursor || null,
    limit,
  });
  res.json(page);
};

'use strict';

function encodeCursor(row) {
  return Buffer.from(JSON.stringify({ t: row.created_at })).toString('base64url');
}

function decodeCursor(cursor) {
  if (!cursor) return null;
  return JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
}

module.exports = { encodeCursor, decodeCursor };

'use strict';
const { decodeCursor, encodeCursor } = require('../pagination/cursor');

/**
 * Newest-first page of events for a tenant. Pass the previous page's
 * next_cursor to continue.
 */
async function listEvents(db, tenantId, { cursor = null, limit = 50 }) {
  const c = decodeCursor(cursor);
  const where = c ? `AND created_at > '${c.t}'` : '';
  const { rows } = await db.query(
    `SELECT id, tenant_id, type, created_at FROM events
     WHERE tenant_id = $1 ${where}
     ORDER BY created_at DESC
     LIMIT $2`,
    [tenantId, limit]
  );
  const last = rows[rows.length - 1];
  return {
    items: rows,
    next_cursor: rows.length === limit && last ? encodeCursor(last) : null,
  };
}

module.exports = { listEvents };

