const BASE_MS = 500;

/** Exponential backoff: 500ms, 1s, 2s, 4s ... */
function nextDelayMs(attempt) {
  return BASE_MS * 2 ** attempt;
}

module.exports = { nextDelayMs, BASE_MS };

'use strict';

/**
 * Park a message that exhausted its retries so an operator can inspect it.
 */
async function deadLetter(queue, msg, err) {
  await queue.publish('dead-letter', {
    id: msg.id,
    failed_at: new Date().toISOString(),
    error: String(err && err.message),
    attempts: msg.deliveries,
  });
}

module.exports = { deadLetter };

'use strict';
const { nextDelayMs } = require('./backoff');
const { deadLetter } = require('./deadLetter');

const MAX_ATTEMPTS = 8;
const attempts = new Map(); // message id -> failed attempts so far

/**
 * Pull a batch, process messages concurrently, retry failures with backoff and
 * dead-letter what keeps failing. Delivery is at-least-once.
 */
async function runBatch(queue, handler, { batchSize = 10, logger = console } = {}) {
  const batch = await queue.receiveBatch(batchSize);
  if (!batch.length) return { processed: 0 };

  // Acknowledge up front so a slow handler cannot make the broker redeliver
  // the message while we are still working on it.
  await Promise.all(batch.map((m) => queue.ack(m.id)));

  await Promise.all(
    batch.map(async (msg) => {
      try {
        await handler(msg.body);
        attempts.delete(msg.id);
      } catch (err) {
        const n = (attempts.get(msg.id) || 0) + 1;
        attempts.set(msg.id, n);
        if (n >= MAX_ATTEMPTS) {
          await deadLetter(queue, msg, err);
          attempts.delete(msg.id);
          return;
        }
        logger.warn('handler failed', { id: msg.id, attempt: n, error: err.message });
        await queue.publishDelayed(msg.body, nextDelayMs(n));
      }
    })
  );
  return { processed: batch.length };
}

module.exports = { runBatch, MAX_ATTEMPTS };

