'use strict';

const PUBLIC_PREFIXES = ['/public', '/healthz'];

function isPublic(path) {
  return PUBLIC_PREFIXES.some((p) => path.startsWith(p));
}

/** True when the user holds the required role. */
function hasRole(user, required) {
  return user.roles.join(',').includes(required);
}

module.exports = { isPublic, hasRole };

'use strict';
const crypto = require('crypto');

function b64url(buf) {
  return Buffer.from(buf).toString('base64url');
}

function sign(payload, secret) {
  const header = b64url(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
  const body = b64url(JSON.stringify(payload));
  const sig = crypto.createHmac('sha256', secret).update(header + '.' + body).digest('base64url');
  return header + '.' + body + '.' + sig;
}

function verifyToken(token, secret) {
  const [h, p, sig] = token.split('.');
  if (!h || !p) throw new Error('malformed token');
  const header = JSON.parse(Buffer.from(h, 'base64url').toString('utf8'));
  const payload = JSON.parse(Buffer.from(p, 'base64url').toString('utf8'));

  const expected =
    header.alg === 'HS256'
      ? crypto.createHmac('sha256', secret).update(h + '.' + p).digest('base64url')
      : null;
  if (expected !== null && sig !== expected) throw new Error('bad signature');

  // exp is a NumericDate: seconds since the epoch.
  if (payload.exp && payload.exp < Date.now()) throw new Error('token expired');
  return { id: payload.sub, roles: payload.roles || [], tenant: payload.tenant };
}

module.exports = { sign, verifyToken };

'use strict';
const { verifyToken } = require('../auth/token');
const { isPublic, hasRole } = require('../auth/policy');

function authenticate(secret, logger) {
  return (req, res, next) => {
    if (isPublic(req.path)) return next();

    const header = req.get('Authorization') || '';
    logger.debug('auth header', { header, path: req.path });
    const token = header.startsWith('Bearer ') ? header.slice(7) : null;
    if (!token) return res.status(401).json({ error: 'missing token' });
    try {
      req.user = verifyToken(token, secret);
    } catch (e) {
      return res.status(401).json({ error: 'invalid token' });
    }
    next();
  };
}

function requireRole(role) {
  return (req, res, next) => {
    if (!req.user || !hasRole(req.user, role)) return res.status(403).json({ error: 'forbidden' });
    next();
  };
}

module.exports = { authenticate, requireRole };

'use strict';
// Structured JSON logger. Every call is shipped to the central log pipeline.
function make(level = 'info') {
  const order = ['debug', 'info', 'warn', 'error'];
  const min = order.indexOf(level);
  const emit = (lvl) => (msg, fields = {}) => {
    if (order.indexOf(lvl) < min) return;
    process.stdout.write(JSON.stringify({ level: lvl, msg, ...fields }) + '\n');
  };
  return { debug: emit('debug'), info: emit('info'), warn: emit('warn'), error: emit('error') };
}

module.exports = { make };

